<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('admin');
$page=max(1,(int)($_GET['page']??1));$perPage=30;$offset=($page-1)*$perPage;$q=trim((string)($_GET['q']??''));
$where='';$params=[];if($q!==''){ $where='WHERE al.action LIKE ? OR al.entity_type LIKE ? OR u.full_name LIKE ? OR u.mobile LIKE ?';$needle='%'.$q.'%';$params=[$needle,$needle,$needle,$needle]; }
$countStmt=db()->prepare('SELECT COUNT(*) FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id '.$where);$countStmt->execute($params);$total=(int)$countStmt->fetchColumn();
$stmt=db()->prepare('SELECT al.*,u.full_name,u.mobile FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id '.$where.' ORDER BY al.created_at DESC LIMIT '.$perPage.' OFFSET '.$offset);$stmt->execute($params);$logs=$stmt->fetchAll();$pages=max(1,(int)ceil($total/$perPage));
$title='لاگ فعالیت‌ها';require __DIR__.'/../partials/header.php';?><div class="card"><div class="class-toolbar"><div><span class="eyebrow">کنترل و امنیت</span><h1>لاگ فعالیت‌ها</h1><p class="muted">ثبت رخدادهای مهم برای پیگیری تغییرات کاربران، کلاس‌ها، آزمون‌ها و پشتیبان‌گیری.</p></div><form class="search-form" method="get"><input name="q" value="<?=e($q)?>" placeholder="جست‌وجو بر اساس کاربر، عملیات یا موجودیت"><button class="btn btn-primary">جست‌وجو</button></form></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>زمان</th><th>کاربر</th><th>عملیات</th><th>موجودیت</th><th>شناسه</th><th>IP</th></tr></thead><tbody><?php if(!$logs):?><tr><td colspan="6" class="muted text-center">رخدادی پیدا نشد.</td></tr><?php else:foreach($logs as $log):?><tr><td><?=e($log['created_at']??'—')?></td><td><?=e($log['full_name']??'سیستم')?><?php if(!empty($log['mobile'])):?><small class="muted"><br><?=e($log['mobile'])?></small><?php endif;?></td><td><span class="badge"><?=e($log['action'])?></span></td><td><?=e($log['entity_type']??'—')?></td><td><?=e((string)($log['entity_id']??'—'))?></td><td dir="ltr"><?=e($log['ip_address']??'—')?></td></tr><?php endforeach;endif;?></tbody></table></div><?php if($pages>1):?><div class="actions" style="margin-top:18px"><?php for($i=1;$i<=$pages;$i++):?><a class="btn <?=($i===$page?'btn-primary':'btn-light')?> btn-sm" href="<?=e(url('admin/audit_logs.php?page='.$i.($q!==''?'&q='.rawurlencode($q):'')))?>"><?=$i?></a><?php endfor;?></div><?php endif;?></div><?php require __DIR__.'/../partials/footer.php'; ?>
